import json
from collections import Counter
from pathlib import Path

path = Path('events.jsonl')
events = [json.loads(line) for line in path.read_text(encoding='utf-8').splitlines() if line.strip()]
events.sort(key=lambda e: (e['seq'], e['msg_id']))

orders = {}
seen = set()
anomalies = []
for e in events:
    if e['msg_id'] in seen:
        anomalies.append({'type': 'duplicate_msg_id', 'msg_id': e['msg_id'], 'order_id': e['order_id'], 'seq': e['seq']})
        continue
    seen.add(e['msg_id'])

    if e['amount'] < 0:
        anomalies.append({'type': 'negative_amount', 'msg_id': e['msg_id'], 'order_id': e['order_id'], 'seq': e['seq']})
        continue

    anomaly = 'unacked' if not e['ack'] else None
    oid = e['order_id']
    op = e['op']
    amount = e['amount']
    order = orders.get(oid)

    if op == 'create':
        if order is None:
            orders[oid] = {'order_id': oid, 'state': 'created', 'paid_total': 0, 'refunded_total': 0}
    elif op == 'pay':
        if order is not None and order['state'] in ('created', 'paid'):
            order['paid_total'] += amount
            order['state'] = 'paid'
    elif op == 'cancel':
        if order is not None:
            if order['state'] == 'created':
                order['state'] = 'cancelled'
            elif order['state'] in ('paid', 'refunded'):
                if anomaly is None:
                    anomaly = 'late_cancel'
    elif op == 'refund':
        if order is not None and order['state'] in ('paid', 'refunded'):
            order['refunded_total'] += amount
            order['state'] = 'refunded' if order['refunded_total'] >= order['paid_total'] else 'paid'
    else:
        raise ValueError(f'unknown op: {op}')

    if anomaly:
        anomalies.append({'type': anomaly, 'msg_id': e['msg_id'], 'order_id': oid, 'seq': e['seq']})

final = [orders[k] for k in sorted(orders)]
print('events', len(events), 'orders', len(final), 'anomalies', len(anomalies), Counter(a['type'] for a in anomalies))
print('JSON_FINAL')
print(json.dumps(final, ensure_ascii=False, indent=2))
print('JSON_ANOMALIES')
print(json.dumps(anomalies, ensure_ascii=False, indent=2))
PY"

