/bin/zsh -c "python3 - <<'PY'
import json
from pathlib import Path

events = [
    json.loads(line)
    for line in Path('events.jsonl').read_text(encoding='utf-8').splitlines()
    if line.strip()
]
events.sort(key=lambda event: (event['seq'], event['msg_id']))

orders = {}
seen_msg_ids = set()
anomalies = []

for event in events:
    msg_id = event['msg_id']
    order_id = event['order_id']
    seq = event['seq']
    amount = event['amount']
    op = event['op']

    if msg_id in seen_msg_ids:
        anomalies.append({
            'type': 'duplicate_msg_id',
            'msg_id': msg_id,
            'order_id': order_id,
            'seq': seq,
        })
        continue
    seen_msg_ids.add(msg_id)

    if amount < 0:
        anomalies.append({
            'type': 'negative_amount',
            'msg_id': msg_id,
            'order_id': order_id,
            'seq': seq,
        })
        continue

    anomaly_type = None if event['ack'] else 'unacked'
    order = orders.get(order_id)

    if op == 'create':
        if order is None:
            orders[order_id] = {
                'order_id': order_id,
                'state': 'created',
                'paid_total': 0,
                'refunded_total': 0,
            }
    elif op == 'pay':
        if order is not None and order['state'] in ('created', 'paid'):
            order['paid_total'] += amount
            order['state'] = 'paid'
    elif op == 'cancel':
        if order is not None:
            if order['state'] == 'created':
                order['state'] = 'cancelled'
            elif order['state'] in ('paid', 'refunded') and anomaly_type is None:
                anomaly_type = 'late_cancel'
    elif op == 'refund':
        if order is not None and order['state'] in ('paid', 'refunded'):
            order['refunded_total'] += amount
